-- plain TIMESTAMP values are read in the session TimeZone
SET TimeZone = 'UTC';

-- one row per minute of January 2025
CREATE TABLE trades AS
SELECT ts, random() AS price
FROM range(TIMESTAMP '2025-01-01', TIMESTAMP '2025-02-01', INTERVAL 1 MINUTE) t(ts);

-- NYSE trading hours on every workday of January (holidays aside)
SELECT count(*), min(ts), max(ts)
FROM trades
WHERE ts IN '[2025-01]T09:30@America/New_York#workday;6h30m';

-- the first hour of trading on the workdays of January 1st to 7th
SELECT count(*) FROM trades WHERE ts IN '2025-01-[01..07]T09:30@America/New_York#workday;1h';

-- the intervals a pattern expands to
SELECT * FROM tick_intervals('[2025-01]T09:30@America/New_York#workday;6h30m') LIMIT 3;

INSTALL timestral FROM community;
LOAD timestral;

-- Hourly series, one per store. The 5M model (~23 MB) is downloaded and cached on first use.
CREATE TABLE sales AS
SELECT g AS store, TIMESTAMP '2026-01-01' + INTERVAL (i) HOUR AS ts, 10 * g + sin(i / 6) AS amount
FROM range(3) a(g), range(500) b(i);

-- Forecast the next 24 hours of every store: median plus 21 quantiles per step.
SELECT store, ts, forecast, q10, q90
FROM sales TIMESTRAL_FORECAST (amount PARTITION BY store ORDER BY ts HORIZON 24);

-- The same with the aggregate, for full control over grouping.
SELECT store, unnest(timestral_forecast(amount ORDER BY ts HORIZON 24), recursive := true)
FROM sales GROUP BY store;

