FROM orcid_works('records/*.xml')
ORDER BY pub_year DESC;

-- 3. Records already in a table: the _xml twin in a lateral join
SELECT r.orcid, a.affiliation_type, a.org_name, a.start_year
FROM records r, orcid_affiliations_xml(r.xml) a;

-- 4. A Public Data File dump, read in place (only the bytes needed)
INSTALL httpfs; LOAD httpfs;
SELECT orcid, given_names, family_name
FROM orcid_person('https://ndownloader.figshare.com/files/<file-id>', max_records := 1000);

-- 5. How a record changed: one snapshot, then two
SELECT event_at, event, kind, label FROM orcid_timeline('record.xml') ORDER BY event_at;
SELECT section, put_code, change, field, old_value, new_value
FROM orcid_changes('2024/record.xml', '2025/record.xml');

-- 6. The same iDs across two dump releases, without unpacking them
WITH pairs AS (
  SELECT orcid, a.xml AS old_xml, b.xml AS new_xml
  FROM orcid_documents('ORCID_2024_10_summaries.tar.gz', members := '*/097/*') a
  FULL JOIN orcid_documents('ORCID_2025_10_summaries.tar.gz', members := '*/097/*') b USING (orcid))
SELECT c.orcid, c.section, c.change, c.field, c.old_value, c.new_value
FROM pairs p, orcid_changes_xml(p.old_xml, p.new_xml) c;

